// ------- helpers -------
function collectArray(sectionObj, key) {
  const arr = Array.isArray((sectionObj || {})[key]) ? (sectionObj[key] || []) : [];
  return arr.filter(x => x != null);
}

// ------- read sections -------
const pe = $("Professional Experience").first().json.output.professional_experience || null;
const ts = $("Skills & Technical").first().json.output.technical_skills || null;
const mo = $("Motivation").first().json.output.motivation || null;
const ed = $("Education & Learning").first().json.output.education_learning || null;
const ss = $("Soft Skills & Behavioral").first().json.output.soft_skills_behavioral || null;
const el = $("Eligibility").first().json.output.eligibility_filters || null;

// Return normalized structure
return [
  {
    json: {
      professional_experience: pe,
      technical_skills: ts,
      motivation: mo,
      education_learning: ed,
      soft_skills_behavioral: ss,
      eligibility_filters: el,
    },
  },
];

const sections = $("Reading Sections").first().json;
const pe = sections.professional_experience;
const ts = sections.technical_skills;
const mo = sections.motivation;
const ed = sections.education_learning;
const ss = sections.soft_skills_behavioral;
const el = sections.eligibility_filters;

// ------- merge all questions & notes -------
const questions = []
  .concat(pe?.questions || [])
  .concat(ts?.questions || [])
  .concat(mo?.questions || [])
  .concat(ed?.questions || [])
  .concat(ss?.questions || []);

const notes = []
  .concat(pe?.notes || [])
  .concat(ts?.notes || [])
  .concat(mo?.notes || [])
  .concat(ed?.notes || [])
  .concat(ss?.notes || []);

// ------- read data -------
const organize = $("Organize data").first().json; // works in Function node too
const jobOffer = $('Organize data').first().json['Job Offer'] || {};

const pillars = $("Compute Pillars").first().json;
const pillar_scores = pillars.pillar_scores;
const confidence_overall = pillars.confidence_overall;

// ------- weights from job offer (fallback to defaults) -------
const pillar_weights = jobOffer.weights || {
  professional_experience: 0.30,
  technical_skills: 0.35,
  motivation: 0.15,
  education_learning: 0.10,
  soft_skills_behavioral: 0.10,
};

// ------- weighted total -------
const total_score = Number(
  Object.keys(pillar_scores).reduce((acc, k) => {
    const w = Number(pillar_weights[k] ?? 0);
    const s = Number(pillar_scores[k] ?? 0);
    return acc + w * s;
  }, 0).toFixed(4)
);

function normalizeEligibility(input) {
  if (!input) return [];

  // unwrap common shape { el: [...] }
  if (Array.isArray(input.el)) input = input.el;

  // already an array?
  if (Array.isArray(input)) {
    return input
      .map(x => x && typeof x === 'object' ? { rule: String(x.rule || '').trim(), ok: Boolean(x.ok) } : null)
      .filter(x => x && x.rule.length);
  }

  // object with numeric keys { "0": {...}, "1": {...} }
  if (typeof input === 'object') {
    return Object.keys(input)
      .sort((a,b) => Number(a) - Number(b))
      .map(k => input[k])
      .map(x => x && typeof x === 'object' ? { rule: String(x.rule || '').trim(), ok: Boolean(x.ok) } : null)
      .filter(x => x && x.rule.length);
  }

  return [];
}

const result = {
  candidate_id: organize.Email || organize["Email"] || null,
  candidate_name: $("Organize data").first().json.Name,
  candidate_phone: $("Organize data").first().json.Phone,
  job_id: jobOffer.id || null,
  run_id: `run_${Date.now()}`,
  scoring_scale: jobOffer.scoring_scale || "1–5",
  rubric: jobOffer.rubric || "",
  timestamp_utc: new Date().toISOString(),

  professional_experience: {...pe},
  technical_skills: {...ts},
  motivation: {...mo},
  education_learning: {...ed},
  soft_skills_behavioral: {...ss},
  eligibility_filters: normalizeEligibility(el),

  overall: {
    pillar_weights,
    pillar_scores,
    total_score,
    confidence_overall,
    questions,
    notes,
  },
};

// ------- return cleaned JSON (fully serializable) -------
return [{ json: JSON.parse(JSON.stringify(result)) }];

// ------- helpers -------
const CONF_MAP = { High: 1, Med: 0.5, Low: 0 };

function confMeanToLabel(v) {
  if (!isFinite(v)) return "Low";
  if (v >= 0.75) return "High";
  if (v >= 0.4) return "Med";
  return "Low";
}

function sectionMean(sectionObj) {
  if (!sectionObj || typeof sectionObj !== "object") return 0;
  if (typeof sectionObj.section_score === "number") return sectionObj.section_score;

  const scores = Object.values(sectionObj)
    .filter((v) => v && typeof v === "object" && "score" in v)
    .map((v) => Number(v.score))
    .filter((n) => Number.isFinite(n));

  if (!scores.length) return 0;
  return scores.reduce((a, b) => a + b, 0) / scores.length;
}

function sectionConfidence(sectionObj) {
  if (!sectionObj || typeof sectionObj !== "object") return null;
  const vals = Object.values(sectionObj)
    .filter((v) => v && typeof v === "object" && "confidence" in v)
    .map((v) => CONF_MAP[v.confidence] ?? 0.5);

  if (!vals.length) return null;
  return vals.reduce((a, b) => a + b, 0) / vals.length;
}

// ------- read input from Step 1 -------
const input = $json;

const { professional_experience: pe, technical_skills: ts, motivation: mo, education_learning: ed, soft_skills_behavioral: ss } = input;

// ------- compute pillar scores -------
const pillar_scores = {
  professional_experience: sectionMean(pe),
  technical_skills: sectionMean(ts),
  motivation: sectionMean(mo),
  education_learning: sectionMean(ed),
  soft_skills_behavioral: sectionMean(ss),
};

// ------- overall confidence -------
const sectionConfs = [pe, ts, mo, ed, ss]
  .map(sectionConfidence)
  .filter((v) => typeof v === "number");

const confidence_overall = confMeanToLabel(
  sectionConfs.length ? sectionConfs.reduce((a, b) => a + b, 0) / sectionConfs.length : 0
);

return [
  {
    json: {
      pillar_scores,
      confidence_overall,
      sections: { pe, ts, mo, ed, ss },
    },
  },
];
